window.REPORT_PRELOAD_CACHE["SNOW.html"] = {"version":"0fa91a7df087061fa25a25761c147cf214d4588b2de8139de4aa2154eb30e0bd","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>Snowflake Inc. (NYSE: SNOW) 深度研究报告：云端数据与 AI 云平台霸主、Consumption 计费弹性与 Agentic AI 商业化突围</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n snowblue: {\n 300: '#7DD3FC',\n 400: '#38BDF8',\n 500: '#0284C7',\n 600: '#02689C',\n 700: '#034E7A',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n cyan: {\n 400: '#22D3EE',\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(56, 189, 248, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #38BDF8;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-snowblue-500 selection:text-navy-950 transition-colors duration-200\">\n\n <!-- 顶部阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-snowblue-600 via-snowblue-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-snowblue-400 to-snowblue-600 flex items-center justify-center font-extrabold text-navy-950 text-xs shadow\">\n SNOW\n </div>\n <div>\n <div class=\"text-[11px] text-snowblue-400 font-semibold tracking-wider uppercase\">NYSE: SNOW · AI Data Cloud</div>\n <div class=\"text-sm font-bold leading-tight\">Snowflake 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">SNOW 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与产品收入架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球云数据与AI巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与自由现金流推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与三情景估值</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球科技与云数据架构研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (FY27 Q3)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-snowblue-400 via-snowblue-500 to-snowblue-600 flex items-center justify-center text-navy-950 font-extrabold text-base shadow-lg shadow-snowblue-500/25\">\n SNOW\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-snowblue-400 bg-snowblue-500/15 px-2 py-0.5 rounded\">NYSE: SNOW</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">Snowflake 深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n AI Data Cloud 领军者 · Consumption 计费弹性与 Agentic AI 智能体商业化提速\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$282.92 <span class=\"text-slate-400 text-[10px]\">($118.3-$384.6)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">FY27 产品营收指引</span>\n <span class=\"font-mono font-bold text-emerald-400\">~$6.07B <span class=\"text-slate-400\">(+36% YoY)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">核心指标与 RPO</span>\n <span class=\"font-mono font-bold text-snowblue-400\">NRR 126% · RPO $9.0B</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-snowblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与产品收入架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球云数据与AI巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与自由现金流推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与三情景估值</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-snowblue-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-snowblue-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-snowblue-500 to-snowblue-600 hover:from-snowblue-600 hover:to-snowblue-700 text-navy-950 text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-snowblue-500/15 text-snowblue-700 dark:text-snowblue-400 font-bold border border-snowblue-500/30\">评级：买入 / AI 云数据核心成长底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">覆盖周期：FY27 财务指引与 Agentic AI 落地验证期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: SNOW</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#38BDF8 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-snowblue-500/20 border border-snowblue-400/40 text-snowblue-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-snowblue-400 animate-pulse\"></span>\n <span>CORE THESIS · Consumption 计费弹性恢复 × Cortex AI & Agentic Marketplace 平台网络效应 × 36% 产品营收高速增长</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n Snowflake Inc. (NYSE: SNOW) 深度研究报告：云端数据与 AI 云平台霸主、Consumption 计费弹性与 Agentic AI 商业化突围\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n Snowflake 凭借其独树一帜的 <strong class=\"text-white\">Data Cloud（数据云）架构</strong> 与按需消耗（Consumption-based）计费模式，在企业级数据治理、跨云共享和 AI 基础设施中确立了绝对的护城河。随着宏观IT支出回暖及 <strong>Cortex AI、Snowflake CoCo、Agentic Marketplace</strong> 的全面落地，公司业务强劲反弹：FY27 全年产品营收预期上调至 <strong class=\"text-snowblue-300\">$60.7亿（同比增长 +36%）</strong>，剩余履约义务（RPO）跃升至 <strong class=\"text-emerald-400\">$90亿（同比 +30%）</strong>，非 GAAP 产品毛利率稳居 <strong>74%</strong> 高位，全面迈向高增长与自由现金流盈余的双轨复利阶段。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">大客户矩阵超预期膨胀</div>\n <div class=\"text-white font-semibold\">T12M 产品营收超 $100 万大客户达 828 家，Forbes Global 2000 渗透率突破 829 家</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">NRR 留存与消费韧性极强</div>\n <div class=\"text-snowblue-400 font-semibold\">净收入留存率（NRR）稳健维持在 126%，展现极高的数据粘性与平台拓展力</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">Agentic AI 与数据工程闭环</div>\n <div class=\"text-emerald-400 font-semibold\">收购 Observe 与 TensorStax，构建从 IT Observability 到智能体协同的端到端生态</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与最新股价</span>\n <span class=\"p-1.5 rounded-lg bg-snowblue-500/15 text-snowblue-600 dark:text-snowblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$98.9B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$282.92</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 随着 AI 数据云平台产品线大超预期，市值稳步重回千亿美元关口附近。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>FY27 产品营收指引</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$6.07B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">+36% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 较此前指引显著上调（前值 $58.4亿 / +31%），彰显企业级计算与存储消耗动能强劲。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>剩余履约义务 (RPO) & NRR</span>\n <span class=\"p-1.5 rounded-lg bg-cyan-500/15 text-cyan-600 dark:text-cyan-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$9.0B</span>\n <span class=\"text-xs font-bold text-cyan-600 dark:text-cyan-400 bg-cyan-500/15 px-2 py-0.5 rounded\">NRR 126%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n RPO 同比大增 +30%（达 $90亿），大客户续费与长期合同锁定能力在SaaS软件中首屈一指。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>非 GAAP 产品毛利与经调 FCF</span>\n <span class=\"p-1.5 rounded-lg bg-snowblue-500/15 text-snowblue-600 dark:text-snowblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">74.0%</span>\n <span class=\"text-xs font-bold text-snowblue-700 dark:text-snowblue-400 bg-snowblue-500/15 px-2 py-0.5 rounded\">FCF Margin 23%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 经调整自由现金流利润率达 23%，展现出规模效应带来的强劲盈利转化能力。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务与产品收入架构 (Business & Revenue Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-snowblue-600 dark:text-snowblue-400\">Section 01 · Business & Revenue Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与产品收入架构：Data Cloud 数据云底座、按需消耗模式与 AI 矩阵协同</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY27 全年产品营收目标 ~$6.07B · 托管于 AWS/Azure/GCP 多云架构</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY23–FY27E 产品营收增长与自由现金流（FCF）演进</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">产品营收从 $2.0B 迅速跃升至超 $6.0B 规模，同时自由现金流转正并高速扩张</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('revenue_fcf')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-snowblue-600 dark:text-snowblue-400 shadow-sm transition cursor-pointer\">视图A：产品营收与FCF规模</button>\n <button onclick=\"switchBizChart('metrics_split')\" id=\"btn-chart-met\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：大客户与留存率拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">Snowflake 核心增长的三大引擎</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-snowblue-500/15 text-snowblue-600 dark:text-snowblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Consumption 模型：算力与存储按需消耗，随企业 AI 数据量爆发同步放大</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 摆脱传统 SaaS 的固定席位授权，Snowflake 采用基于计算资源（Virtual Warehouses）与存储消耗的定价模式，完美适配企业无上限的数据湖仓膨胀需求。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Cortex AI 与 Agentic Marketplace 驱动智能化升级</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 通过内置大模型服务 Cortex AI、Snowflake CoCo 及智能体发现市场，让企业直接在统一安全的数据治理边界内构建和运行 AI Agent，大幅提升吞吐量。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-cyan-500/15 text-cyan-600 dark:text-cyan-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">跨云互通与 Data Share 构筑的网络外部性</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 数据无需复制即可在 AWS、Azure 和 Google Cloud 之间安全共享，吸引 829 家 Forbes Global 2000 企业入驻，形成极强的供需两端网络效应。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">大客户护城河指标</span>\n <span class=\"font-bold text-snowblue-600 dark:text-snowblue-400\">百万美元营收客户突破 828 家</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-snowblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-snowblue-500/15 text-snowblue-700 dark:text-snowblue-400 text-xs font-bold\">核心营收绝对支柱 · 占总产品营收 ~95%+</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">毛利率 ~74%</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 数据云产品矩阵（Data Warehouse + Data Lake + Data Engineering）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 涵盖结构化与半结构化数据的高性能存储与极速 SQL 查询。通过存算分离（Storage & Compute Separation）架构，企业可独立扩展计算节点以处理海量并发查询，产品毛利率常年维持在 <strong>74%–75%</strong> 的顶尖软件水准。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>FY27 产品营收指引 ~$6.07B (+36%)</span>\n <span class=\"text-snowblue-600 dark:text-snowblue-400 font-semibold\">存算分离架构标杆</span>\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">高成长第二曲线 · AI 与协作生态</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">RPO 高达 $9.0B</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. AI、应用与跨云协作生态（Cortex AI + Marketplace + Observe）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 通过收购 <strong>Observe</strong> 进入 500 亿美元以上的 IT 运维与可观测性市场，并推出 <strong>Cortex Code</strong> 与 <strong>Agentic Marketplace</strong>。Snowflake 正在将数据平台从简单的“仓库”升级为企业运行 AI 智能体（AI Agents）的核心神经中枢。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>剩余履约义务 RPO 同比 +30%</span>\n <span class=\"text-emerald-600 dark:text-emerald-400 font-semibold\">AI Agent 基础底座爆发</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与四重核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：存算分离、多云互通与 126% NRR 留存壁垒</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球企业级云数据事实标准)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-snowblue-500/15 text-snowblue-600 dark:text-snowblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">跨云多云架构（AWS / Azure / GCP）中立性</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 不同于各大公有云厂商强绑定的自家数据服务（如 Redshift 或 BigQuery），Snowflake 实现了三大主流云平台的无缝跨云运行，消除企业“数据孤岛”与厂商锁死风险。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Data Share 强大网络外部性</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 随着全球 829 家世界 2000 强企业和海量供应商入驻 Snowflake Data Marketplace，买卖双方可以直接在平台上进行安全、实时的零拷贝数据交换，网络效应极强。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-cyan-500/15 text-cyan-600 dark:text-cyan-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">126% 高留存率与高切换成本</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 核心业务系统、历史数据湖与 AI 管道一旦全面托管在 Snowflake 上，企业迁移至竞品的重构成本极高，从而支撑高达 126% 的净收入留存率（NRR）。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Snowpark 与 Cortex AI 开发者生态</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n Snowpark 允许开发人员使用 Python、Java 等原生语言直接在数据端运行复杂代码，配合 Cortex AI 大模型加速，彻底打破了传统 SQL 引擎的功能边界。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">云数据与 AI 基础设施巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Snowflake (SNOW) vs Databricks vs AWS Redshift vs Google BigQuery（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 全球云数据与AI巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-snowblue-600 dark:text-snowblue-400\">Section 03 · Global Cloud Data & AI Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球云数据与 AI 巨头横向对比：多云中立定位、36% 营收增速与生态协同</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-snowblue-500 text-navy-950 shadow-sm transition cursor-pointer\">全部巨头</button>\n <button onclick=\"filterCompetitors('cloud')\" data-filter=\"cloud\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">云厂商自有数据服务</button>\n <button onclick=\"filterCompetitors('independent')\" data-filter=\"independent\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">独立云数据与AI平台</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与核心平台</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心架构优势</th>\n <th class=\"py-4 px-4 min-w-[140px]\">AI 与大模型进展</th>\n <th class=\"py-4 px-4 min-w-[100px]\">营收增速 (YoY)</th>\n <th class=\"py-4 px-4 min-w-[115px]\">毛利率水平</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与竞合定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"independent\" class=\"bg-snowblue-500/5 dark:bg-snowblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-snowblue-500 text-navy-950 text-[10px] font-extrabold\">核心标的</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">Snowflake (SNOW)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Data Cloud / Cortex AI / Observe</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">真正实现 AWS / Azure / GCP 跨云打通</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">Cortex AI + Agentic Mkt</span>\n </td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">~36%</td>\n <td class=\"py-4 px-4 font-mono font-bold text-snowblue-600 dark:text-snowblue-400\">~74.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>企业级数据与 AI 中立平台标杆：</strong>客户留存高达 126%，大客户数量爆发，数据共享网络效应无出其右。\n </td>\n </tr>\n\n <tr data-category=\"independent\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Databricks (未上市)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Lakehouse / Mosaic AI / Delta Lake</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">开源数据湖泊技术与 AI 强绑定</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-snowblue-500/15 text-snowblue-700 dark:text-snowblue-400\">Mosaic AI + DBRX 开源模型</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~50%+ (私有)</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~70% 估计</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>AI 研发与机器学习的最强竞争对手：</strong>在数据科学和生成式 AI 训练领域极具统治力，与 Snowflake 在企业级数仓和 AI 治理上形成直接竞争。\n </td>\n </tr>\n\n <tr data-category=\"cloud\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">AWS (Amazon Redshift / Athena)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Amazon S3 + Bedrock 体系</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">AWS 基础设施底座与成本聚合优势</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">Bedrock AI 智能体集成</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~15%-20%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高 (云基础设施分摊)</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>云厂商原生竞争者：</strong>对纯 AWS 用户具有价格吸引力，但缺乏 Snowflake 的跨云中立性与优雅的多云数据共享体验。\n </td>\n </tr>\n\n <tr data-category=\"cloud\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Google Cloud (BigQuery)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">BigQuery + Vertex AI</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">无服务器架构与超大规模实时分析</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">Gemini 深度原生集成</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~20%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">高</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>AI 原生数据巨头：</strong>凭借 Gemini 模型在 BigQuery 中直接提供强大的文本与多模态分析能力，是 Snowflake 在大企业客户中的有力对手。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球云数据与 AI 平台营收增速与产品毛利率横向对照</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">Snowflake 凭借 ~36% 的产品营收增速与 74% 毛利率，在独立云数据板块保持强劲领跑地位</p>\n </div>\n <span class=\"text-xs font-semibold text-snowblue-700 dark:text-snowblue-400 bg-snowblue-500/15 px-2.5 py-1 rounded\">36% 增速与 74% 毛利率双优</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与自由现金流推演 (Financial Health & Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & FCF Compound Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与现金流推演：43亿现金储备、23% FCF 利润率与成长复利模型</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">现金及短期投资 ~$43亿 · 零有息负债结构</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-snowblue-600 dark:text-snowblue-400 uppercase\">Cash & Investments</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$4.3B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 资产负债表极其稳健，持有逾 43 亿美元现金及有价证券，且无长期有息债务，为高强度研发与战略并购提供坚实底气。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Adjusted FCF Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">23.0%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 经调整自由现金流利润率稳步攀升至 23%，全年自由现金流规模突破 11–12 亿美元，彻底告别纯烧钱 SaaS 阶段。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-cyan-600 dark:text-cyan-400 uppercase\">Remaining Performance Obligation</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$9.0B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 剩余履约义务（RPO）达 90 亿美元（同比增长 +30%），合同锁定效应为未来数年的营收变现提供极高可见度。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Net Revenue Retention</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">126%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n NRR 稳定在 126%，展现出现有客户在平台上持续加大算力消耗和横向采购 AI 服务的强烈意愿。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY22–FY27E 产品营收增长与非 GAAP 营业利润率演进趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">公司在保持 30% 以上高速营收增长的同时，非 GAAP 营业利润率与现金流兑现效率持续优化</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-snowblue-700 dark:text-snowblue-400 bg-snowblue-500/15 px-2.5 py-1 rounded\">规模效应驱动盈利能力稳步释放</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <!-- 交互式 Snowflake 长期成长与估值推演器 -->\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-snowblue-400 font-bold\">\n <span>CLOUD & AI GROWTH COMPOUNDING ENGINE · 长期营收与估值推演模拟器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">Snowflake 长期营收与估值市值动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 $282.92 | 当前产品营收 ~$6.07B | 支持调整未来产品营收复合增速与远期 P/S 估值倍数</p>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始投资模拟本金 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$50,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"10000\" max=\"200000\" step=\"10000\" value=\"50000\" oninput=\"updateSnowSimulator()\" class=\"w-full accent-[#38BDF8] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">预测持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">5 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"5\" oninput=\"updateSnowSimulator()\" class=\"w-full accent-[#38BDF8] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">产品营收年均复合增速 (CAGR)</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">25.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"15\" max=\"35\" step=\"1\" value=\"25\" oninput=\"updateSnowSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">期末市销率 P/S 估值倍数假设</span>\n <span id=\"sim-ps-label\" class=\"font-mono font-bold text-snowblue-400 text-sm\">12.0x</span>\n </div>\n <input id=\"sim-ps\" type=\"range\" min=\"8\" max=\"22\" step=\"1\" value=\"12\" oninput=\"updateSnowSimulator()\" class=\"w-full accent-[#38BDF8] cursor-pointer\">\n </div>\n </div>\n\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计产品营收规模</div>\n <div id=\"sim-final-rev\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$18.5B</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">基于设定 CAGR 推演的未来年营收</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计合理总市值</div>\n <div id=\"sim-final-mcap\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-snowblue-400 mt-1.5\">$222.0B</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">对应产品营收与 P/S 乘积</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末投资账户总价值</div>\n <div id=\"sim-final-val\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">$111,200</div>\n <div id=\"sim-total-return\" class=\"text-xs text-slate-400 mt-1.5\">模拟持有期总回报率</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末推演年化回报率 (CAGR)</div>\n <div id=\"sim-annualized-return\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-cyan-400 mt-1.5\">+17.3%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">复合年化增长回报表现</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">AI 数据中枢 + 消费反弹</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Agentic AI 浪潮下的底层数据刚需：</strong>企业构建智能体（AI Agents）的前提是拥有干净、统一且受治理的数据。Cortex AI 与 Snowpark 完美契合这一超级趋势。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Consumption 弹性全面复苏：</strong>宏观IT预算收紧周期已过，FY27 产品营收增速回升至 36%，大客户数量与 RPO（$90亿）保持高增。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>自由现金流拐点已至：</strong>经调整 FCF 利润率突破 23%，账面现金逾 43 亿美元，具备极强的内生造血与外延并购能力。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">云厂商竞争 + 估值敏感</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>来自公有云厂商与 Databricks 的双重挤压：</strong>AWS、GCP 以及 Databricks 在 AI 湖仓（Lakehouse）领域的激烈竞争可能在部分价格敏感型客户中引发分流。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>Consumption 模式在宏观波动下的不确定性：</strong>按需付费意味着一旦客户优化云端算力消耗，营收增速可能出现短期剧烈波动。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>高估值对利率和业绩容错率要求严苛：</strong>股价反弹至 $282 后，市场对高成长软件股的估值容错空间收窄，任何季度指引微调都易引发波动。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-snowblue-600 dark:text-snowblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景目标价与云数据组合策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：科技成长组合核心标的 · 逢大盘回调分批积极布局</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">16.0x–18.0x P/S ($360–$410)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>Agentic AI 应用爆发超预期，Cortex AI 与 Agentic Marketplace 贡献爆发式增量算力消耗，产品营收增速持续保持 35%+，NRR 回升至 130% 以上。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 潜在上涨空间：+30% 至 +45%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-snowblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-snowblue-500/15 text-snowblue-700 dark:text-snowblue-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-snowblue-600 dark:text-snowblue-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">11.0x–13.0x P/S ($260–$310)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>FY27 产品营收顺利实现 $60.7亿 目标（+36% YoY），大客户拓展与 FCF 利润率（23%）稳步兑现，估值在中枢区间理性震荡。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-snowblue-600 dark:text-snowblue-400\">\n 稳健年化回报：中枢震荡、长线增值\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">7.0x–9.0x P/S ($160–$200)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观经济再度走弱导致企业云端 IT 预算削减，Consumption 消耗放缓，Databricks 或三大云厂商价格战侵蚀毛利率。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在回撤风险：-25% 至 -40%（依靠 $43亿 现金构筑底部）\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险评估与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 巨头与 Databricks 竞争加剧</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">开源 Lakehouse 与公有云原生服务的价格和生态分流</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n Databricks 在 AI 机器学习和开源数据湖社区拥有强大号召力，需持续追踪 Snowflake 在 AI 算力定价和开发者留存上的竞争动态。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · Consumption 模型对宏观景气度的敏感性</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">按需消耗模式在企业缩减IT开支时的短期波动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 当客户进行极端的云端资源优化（Cloud Cost Optimization）时，SQL 查询与存储消耗会迅速放缓，直接传导至当季产品营收。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-cyan-500/10 text-cyan-600 dark:text-cyan-400 text-xs font-bold\">03 · 大模型 API 成本与毛利率稀释</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">Cortex AI 大模型调用成本对非 GAAP 利润率的影响</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 随着越来越多的企业客户在平台上运行大规模 AI 智能体任务，第三方基础大模型的 API 成本与底层算力消耗是否会侵蚀毛利率值得密切监控。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 科技股整体估值中枢波动</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">长端美债收益率与高成长科技板块风险偏好回撤</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 作为高成长美股标的，SNOW 的估值对宏观利率走势敏感，利率再度走高可能带来估值收缩压力。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-snowblue-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与“云数据与 AI”协同策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 核心成长底仓配置</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 将 Snowflake 作为云计算与企业级 AI 基础设施的核心进攻仓位，分享其大客户数量膨胀与 Agentic AI 商业化红利。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-snowblue-400 mb-1\">2. 逢回调分批吸纳纪律</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 股价在近期反弹至 $282 后，建议避免盲目追高；若受大盘或科技板块波动回踩至估值安全边际区，则果断分批加仓。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 定期跟踪核心 KPI</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 严格按照下方季度核查清单，密切跟踪产品营收增速、NRR（>125%）、百万美元客户数及 RPO 变动，确保投资逻辑持续兑现。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-snowblue-500/15 text-snowblue-700 dark:text-snowblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选每季财报发布后已验证达标的关键业务指标（勾选状态自动本地保存），持续追踪 Snowflake 业务基本面与成长护城河：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-snowblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 产品营收同比增速是否稳守 30%–35%+ 区间</span>\n <span class=\"text-[11px] font-mono text-snowblue-600 dark:text-snowblue-400 font-semibold shrink-0\">核心增长锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 验证 FY27 全年产品营收 $60.7亿（+36% YoY）目标及每季度实际交付是否符合预期。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-snowblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 净收入留存率 (NRR) 是否保持在 125% 以上高位</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">客户粘性晴雨表</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 当前 NRR 稳定在 126%，需追踪现有客户在平台上的算力消耗升级与 AI 应用扩展速度。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-snowblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. T12M 产品营收超 $100 万大客户数及 Global 2000 渗透</span>\n <span class=\"text-[11px] font-mono text-cyan-600 dark:text-cyan-400 font-semibold shrink-0\">大企业拓展指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 追踪百万美元级客户（当前 828 家）与福布斯全球 2000 强企业（当前 829 家）的净增数量与渗透率。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-snowblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 剩余履约义务 (RPO) 是否维持 30%+ 强劲增速</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">合同锁定可见度</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查 RPO（当前达 $90 亿美元）的季度绝对额增长，确保大企业长期合同锁定动能不减。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-snowblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 非 GAAP 产品毛利率（74%+）与经调整 FCF 利润率（23%）</span>\n <span class=\"text-[11px] font-mono text-snowblue-600 dark:text-snowblue-400 font-semibold shrink-0\">盈利与现金转化</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监控云端算力和 AI 大模型 API 成本波动对 74% 产品毛利率和 23% 自由现金流利润率的摊薄或增厚效应。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0284C7] focus:ring-snowblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. Cortex AI、Snowflake CoCo 与 Agentic Marketplace 商业化落地</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">AI 变现第二曲线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪 AI 相关产品给整体 Consumption 带来的额外消耗占比及客户采用率。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- 页脚免责声明 -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>Snowflake Inc. (NYSE: SNOW) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：FY27 财报指引及 2026 年 11 月市场一致预期</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于 Snowflake 官方财务报告（10-Q/10-K）、业绩电话会议披露数据及全球云计算与 AI 行业调研资料整理生成，旨在提供结构化的产业分析与估值推演框架。报告中涉及的营收预测、自由现金流模拟、三情景目标价及估值推演均基于特定假设条件，不构成任何证券买卖建议或收益承诺。请在独立核实后审慎决策。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互脚本与 Chart.js 可视化 -->\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-snowblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-snowblue-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-snowblue-500', 'text-navy-950', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-snowblue-500', 'text-navy-950', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n // 长期营收与估值市值模拟器\n function updateSnowSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n const psMultiple = parseFloat(document.getElementById('sim-ps').value);\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n document.getElementById('sim-ps-label').textContent = psMultiple.toFixed(1) + 'x';\n\n const baseRev = 6.07; // FY27 产品营收约 $6.07B\n const g = growthPct / 100;\n const finalRev = baseRev * Math.pow(1 + g, years);\n const finalMcap = finalRev * psMultiple; // 单位：B ($)\n const finalVal = (principal / (6.07 * 16.0)) * finalMcap; // 对应本金份额按市值比例放大\n const totalReturnPct = ((finalVal - principal) / principal) * 100;\n const annualizedReturn = (Math.pow(finalVal / principal, 1 / years) - 1) * 100;\n\n document.getElementById('sim-final-rev').textContent = '$' + finalRev.toFixed(2) + 'B';\n document.getElementById('sim-final-mcap').textContent = '$' + finalMcap.toFixed(1) + 'B';\n document.getElementById('sim-final-val').textContent = '$' + Math.round(finalVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `模拟持有期总回报 +${totalReturnPct.toFixed(1)}%`;\n document.getElementById('sim-annualized-return.textContent` = (annualizedReturn >= 0 ? '+' : '') + annualizedReturn.toFixed(1) + '%';\n document.getElementById('sim-annualized-return').textContent = (annualizedReturn >= 0 ? '+' : '') + annualizedReturn.toFixed(1) + '%';\n }\n\n const KPI_STORAGE_KEY = 'snow_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'revenue_fcf';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const revFcfConfig = {\n type: 'bar',\n data: {\n labels: ['FY23', 'FY24', 'FY25', 'FY26', 'FY27E'],\n datasets: [\n {\n label: '产品营收 ($B)',\n data: [1.94, 2.67, 3.43, 4.47, 6.07],\n backgroundColor: '#38BDF8',\n borderRadius: 4,\n stack: 'rev'\n },\n {\n type: 'line',\n label: '自由现金流 FCF ($B)',\n data: [0.49, 0.81, 0.83, 1.12, 1.40],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n min: 0,\n max: 7,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n const metricsSplitConfig = {\n type: 'bar',\n data: {\n labels: [\n '净收入留存率 NRR (%)',\n '产品营收同比增速 YoY (%)',\n '非 GAAP 产品毛利率 (%)',\n '经调整自由现金流利润率 (%)',\n '剩余履约义务 RPO 增速 (%)'\n ],\n datasets: [\n {\n label: '核心运营指标 (%)',\n data: [126, 36, 74, 23, 30],\n backgroundColor: [\n '#38BDF8',\n '#0284C7',\n '#06B6D4',\n '#10B981',\n '#6366F1'\n ],\n borderRadius: 6,\n barThickness: 24\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `指标数值: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 140,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'revenue_fcf' ? revFcfConfig : metricsSplitConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnMet = document.getElementById('btn-chart-met');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'revenue_fcf') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-snowblue-600 dark:text-snowblue-400 shadow-sm transition cursor-pointer';\n btnMet.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = 'FY23–FY27E 产品营收增长与自由现金流（FCF）演进';\n subEl.textContent = '产品营收从 $2.0B 迅速跃升至超 $6.0B 规模，同时自由现金流转正并高速扩张';\n } else {\n btnMet.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-snowblue-600 dark:text-snowblue-400 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = 'Snowflake 核心业务运营与效率指标拆解';\n subEl.textContent = 'NRR 保持 126% 高位，产品毛利率 74%，展现软件行业罕见的成长与盈利双重爆发力';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '跨云多云中立性',\n '数据共享网络效应',\n '高留存与切换成本',\n 'AI 与开发者生态',\n '自由现金流与毛利率'\n ],\n datasets: [\n {\n label: 'Snowflake (SNOW)',\n data: [9.8, 9.6, 9.5, 9.0, 9.2],\n borderColor: '#38BDF8',\n backgroundColor: 'rgba(56, 189, 248, 0.24)',\n pointBackgroundColor: '#38BDF8',\n borderWidth: 2.5\n },\n {\n label: 'Databricks',\n data: [8.5, 8.0, 8.5, 9.8, 8.0],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: 'AWS Redshift / GCP BigQuery',\n data: [7.0, 7.5, 8.8, 8.5, 9.5],\n borderColor: '#06B6D4',\n backgroundColor: 'rgba(6, 182, 212, 0.12)',\n pointBackgroundColor: '#06B6D4',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n 'Snowflake (SNOW · 独立云数据标杆)',\n 'Databricks (AI与湖仓生态)',\n 'Google Cloud (BigQuery 数据与AI)',\n 'AWS (Redshift 云原生数仓)'\n ],\n datasets: [\n {\n label: '产品与服务营收增速 YoY (%)',\n data: [36.0, 50.0, 20.0, 18.0],\n backgroundColor: '#38BDF8',\n borderRadius: 5,\n barThickness: 16\n },\n {\n label: '产品/服务毛利率 Margin (%)',\n data: [74.0, 70.0, 75.0, 72.0],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 16\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 70,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['FY23', 'FY24', 'FY25', 'FY26', 'FY27E'],\n datasets: [\n {\n type: 'bar',\n label: '产品营收 ($B)',\n data: [1.94, 2.67, 3.43, 4.47, 6.07],\n backgroundColor: 'rgba(56, 189, 248, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '产品毛利率 (%)',\n data: [75.0, 75.5, 75.2, 75.0, 74.0],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y'\n ? `${ctx.dataset.label}: $${ctx.parsed.y.toFixed(2)}B`\n : `${ctx.dataset.label}: ${ctx.parsed.y.toFixed(1)}%`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 0,\n max: 8,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v.toFixed(1) + 'B' },\n title: { display: true, text: '产品营收 ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 60,\n max: 90,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => v + '%' },\n title: { display: true, text: '产品毛利率 (%)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateSnowSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>"};
